import{z as i,x as s,o as B,c as p,q as n,j as l,D as e,d as a,s as A,S as r,b as t}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"稀疏自编码器的工程实践","description":"","frontmatter":{"title":"稀疏自编码器的工程实践","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/xai-sae-practice.md","filePath":"llm/xai-sae-practice.md","lastUpdated":1791063341000}'),m={name:"llm/xai-sae-practice.md"};function d(c,E,D,h,C,_){const o=s("Mermaid");return B(),p("div",null,[E[2]||(E[2]=n('<h1 id="稀疏自编码器的工程实践" tabindex="-1">稀疏自编码器的工程实践 <a class="header-anchor" href="#稀疏自编码器的工程实践" aria-label="Permalink to &quot;稀疏自编码器的工程实践&quot;">​</a></h1><div class="epigraph"><p>字典学习的想法三行讲完；把一个能用的字典训出来，是位点、数据、宽度与健康监控层层做对的工程。</p><footer>—— 据 Bricken et al., 2023 与 Templeton et al., 2024 的实验配置整理</footer></div><p><a href="/llm/aeval-map">上一课</a>把对齐评测收成九步决策单与四条不变量：政策先行、成对报告、版本冻结、最坏值给门禁，行为侧的深钻交了卷。本课是「可解释性应用」的第一课，沿用同一条纪律：读数要验收，解释不是故事，是产出要验收的工程。<a href="/llm/sae-sparse-autoencoder">SAE 的损失与验收门</a>已把原理讲清；本课只写把它跑成项目的那一半——位点、激活数据管线、宽度与架构的决策顺序、训练健康度。后面的特征验证、电路自动化、表征读写都默认你手里有一个口径清楚、训练健康的字典。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把 SAE 写成目标函数只要三行，跑通一个项目要先答一串账：激活从哪个位点抓、抓多少、怎么流；字典多宽、什么架构、超参按什么顺序定；训练是健康的，还是「损失在降、字典在死」。这些账不是实现细节。位点选错，特征的语义类别整体漂移；管线上没做中心化与归一化，重构损失与稀疏度在不同运行之间没有公共纵轴；死特征率失控，有效字典比账面窄一个量级，解释力随之虚高。</p><p><span class="marginnote">SAE 一句话翻译：它是个「解释器」小网络——输入是模型内部的一个激活向量，中间层维度远大于输入（叫「过完备」），但每次只许少数几个单元亮着。直觉上像病历：病人的状态只有一个，但描述它的「病因条目」有几万条，一次只勾中两三条。这两三条勾选，就是我们要的「稀疏特征」。</span></p><p>上一课的教训在这里原样成立：口径不清的字典比没有字典更糟——拿一支没对过焦的透镜看模型，还以为自己看见了东西。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按四个决策走，顺序不能换。</p><p><strong>位点先行。</strong> 残差流是下游读写的总线，可加性好；MLP 输出带特权基，语义有但叠加密；注意力输出是第三套混合。位点决定特征的语义，不同位点的字典互不通用，选定后不能中途换。残差中层是多数套件的主实验面，<a href="/llm/scaling-monosemanticity">Scaling Monosemanticity</a> 即是如此：太浅多词法，太深已近解嵌。</p><p><span class="marginnote">初学者容易以为在 MLP 输出训的字典，可以顺手套去解释残差流——不行。位点不同，激活的语义与几何都不同，特征编号即使原样搬过去，含义已经完全对不上。这就像把心电图的判读手册拿来读脑电图：波形都在，词汇表作废。</span></p><p><strong>数据管线。</strong> 用 hook 截获选定位点在大量 token 上的激活，流式喂训练：先中心化（减均值或把均值吃进 \\(b_{\\mathrm{dec}}\\)），再按范数归一，让重构误差跨运行可比。<a href="/llm/towards-monosemanticity">Towards Monosemanticity</a> 用了 80 亿个激活样本——稀疏特征的长尾靠它铺开。</p><p><span class="marginnote">80 亿个激活样本是什么概念：每个 token 过一层产生一个激活向量，80 亿样本相当于记录约 80 亿个 token 位置的内部状态——几部小说体量的语料远远不够，得按「让模型读半个互联网」的量级准备数据。原因：稀有概念（冷门语言、生僻代码模式）的长尾特征，出现频率太低，样本少了它们根本没机会被字典学到。</span></p><p><strong>宽度与架构，缩放律先行。</strong> 先在小宽度上扫架构（ReLU、JumpReLU、Gated、TopK）与稀疏系数，用损失与平均 \\(L_0\\) 拟合缩放律，再外推目标宽度的超参。大宽度上网格搜索不可行；没有缩放律的大字典只是一个无法解释的单点。</p><p><strong>健康监控。</strong> 重构 MSE、平均 \\(L_0\\)、死特征率三条曲线同盯；死特征用重采样拉回——重新初始化到重构残差大的方向；拉不回的部分计入误差账。</p>',15)),(B(),l(r,null,{default:e(()=>[A(o,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOOK%5B%22hook%20%E6%88%AA%E8%8E%B7%E4%BD%8D%E7%82%B9%E6%BF%80%E6%B4%BB%22%5D%20--%3E%20NORM%5B%22%E4%B8%AD%E5%BF%83%E5%8C%96%20%2B%20%E8%8C%83%E6%95%B0%E5%BD%92%E4%B8%80%22%5D%0A%20%20NORM%20--%3E%20ENC%5B%22%E7%BC%96%E7%A0%81%EF%BC%9A%E6%9E%B6%E6%9E%84%20%C3%97%20%E5%AE%BD%E5%BA%A6%22%5D%0A%20%20ENC%20--%3E%20F%5B%22%E7%A8%80%E7%96%8F%E7%B3%BB%E6%95%B0%20f%22%5D%0A%20%20F%20--%3E%20DEC%5B%22%E8%A7%A3%E7%A0%81%E9%87%8D%E6%9E%84%22%5D%0A%20%20DEC%20--%3E%20LOSS%5B%22MSE%20%2B%20%E7%A8%80%E7%96%8F%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20F%20--%3E%20MON%5B%22%E7%9B%91%E6%8E%A7%EF%BC%9AL0%20%E4%B8%8E%E6%AD%BB%E7%89%B9%E5%BE%81%E7%8E%87%22%5D%0A%20%20MON%20--%3E%7C%E6%AD%BB%E7%89%B9%E5%BE%81%E8%BF%87%E5%A4%9A%7C%20RES%5B%22%E9%87%8D%E9%87%87%E6%A0%B7%E5%88%B0%E6%AE%8B%E5%B7%AE%E5%A4%A7%E7%9A%84%E6%96%B9%E5%90%91%22%5D%0A%20%20RES%20--%3E%20ENC%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[a("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,[a("缩放律为什么先行：编码器是把迭代稀疏推断换成一次矩阵乘，训练目标非凸，超参在宽度之间不平移，只能靠小宽度上的标度关系外推。死特征是结构性现象与工程失误的叠加：过完备字典必然有空转原子，"),t("a",{href:"/llm/dictionary-learning-interp"},"字典学习课"),a("讲过分裂与合并的几何；而学习率与重采样节奏决定空转面有多大。监控要区分二者：重采样救得回的是工程面，救不回的结构面应写进报告，而不是用高膨胀倍数遮过去。")],-1)),(B(),l(r,null,{default:e(()=>[A(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E4%BD%8D%E7%82%B9%22%5D%20--%3E%7C%22%E6%8D%A2%E4%BD%8D%E7%82%B9%E7%AD%89%E4%BA%8E%E8%AF%AD%E4%B9%89%E6%95%B4%E4%BD%93%E6%BC%82%E7%A7%BB%22%7C%20DA%5B%22%E6%95%B0%E6%8D%AE%E7%AE%A1%E7%BA%BF%EF%BC%9A%E4%B8%AD%E5%BF%83%E5%8C%96%20%2B%20%E5%BD%92%E4%B8%80%22%5D%0A%20%20DA%20--%3E%7C%22%E4%B8%8D%E5%BD%92%E4%B8%80%E5%88%99%E8%B7%A8%E8%BF%90%E8%A1%8C%E6%97%A0%E5%85%AC%E5%85%B1%E7%BA%B5%E8%BD%B4%22%7C%20SC%5B%22%E7%BC%A9%E6%94%BE%E5%BE%8B%EF%BC%9A%E5%B0%8F%E5%AE%BD%E5%BA%A6%E6%89%AB%E5%8F%82%E5%86%8D%E5%A4%96%E6%8E%A8%22%5D%0A%20%20SC%20--%3E%7C%22%E8%B7%B3%E8%BF%87%E5%88%99%E5%A4%A7%E5%AD%97%E5%85%B8%E6%98%AF%E6%97%A0%E6%B3%95%E8%A7%A3%E9%87%8A%E7%9A%84%E5%8D%95%E7%82%B9%22%7C%20HM%5B%22%E5%81%A5%E5%BA%B7%E7%9B%91%E6%8E%A7%EF%BC%9AMSE%20%2F%20L0%20%2F%20%E6%AD%BB%E7%89%B9%E5%BE%81%E7%8E%87%22%5D%0A%20%20HM%20--%3E%7C%22%E9%87%8D%E9%87%87%E6%A0%B7%E6%95%91%E4%B8%8D%E5%9B%9E%E7%9A%84%E7%BB%93%E6%9E%84%E9%9D%A2%22%7C%20REP%5B%22%E8%AF%AF%E5%B7%AE%E8%B4%A6%E4%B8%8E%E5%85%83%E6%95%B0%E6%8D%AE%E5%85%A5%E6%8A%A5%E5%91%8A%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">这张图回答「四步为什么不能换序」：每一步的输出是下一步的前提——位点决定抓什么数据，归一决定指标可比，缩放律决定大宽度超参从哪来，健康监控决定敢不敢把字典交付给后面的验证与电路分析。跳过任何一步，返工的都不是那一步本身，而是它下游的全部工序。</span></p><p>重构残差同理。字典没覆盖的方向全部堆进误差项，误差占比应随宽度下降；不降，说明字典在错的地方变宽。训练完成后，位点、宽度、架构、数据量、checkpoint 一并写进字典的元数据——下一课的验收、后课的电路分析都按这份元数据解释结果。</p><p><span class="marginnote">Templeton et al., 2024 在 Claude 3 Sonnet 中层残差训到三千四百万特征。按 \\(d_{\\mathrm{model}}\\) 四千量级粗算，单个解码矩阵约 \\(1.4\\times10^{11}\\) 参数，bf16 下数百 GB：字典本身就是需要调度的大模型，「缩放律先行」不是风格偏好，是算力账。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做验证：训出来的特征是不是真的、怎么规模化验收，下一课。位点与宽度一经选定就绑定语义——换 checkpoint 或换宽度，特征编号整体作废，跨字典比较必须重走验收。自训与开放套件（<a href="/llm/gemma-scope">Gemma Scope</a>）是预算题：开放套件覆盖主流开源模型、省下本课全部工序，但位点与宽度受限；自训自由，代价是四步全走并自己兜住口径。工程也换不来完备性：字典再宽，误差节点里的方向仍可能是模型在用的。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>工程顺序钉死：位点 → 数据管线 → 缩放律外推超参 → 健康监控，顺序换了后面全返工。</li><li>三条健康曲线同盯：重构 MSE、平均 \\(L_0\\)、死特征率；误差占比要随宽度下降。</li><li>死特征与分裂是结构性现象，重采样只救工程面；救不回的写进报告。</li><li>位点、宽度、checkpoint 绑定特征语义；跨字典比较必须重走验收。</li><li>出处：Bricken et al., <em>Towards Monosemanticity</em>, 2023；Templeton et al., <em>Scaling Monosemanticity</em>, 2024；损失与验收口径见本栏 SAE 基础课。</li></ul>',7))])}const u=i(m,[["render",d]]);export{S as __pageData,u as default};
